"""Partie Entretien de la page Mission : environ 140 questions avec réponses modèles, par thème.
Réponses à adapter à son propre parcours (remplacer les exemples génériques par les siens)."""
import runpy, pathlib, html as H
g = runpy.run_path(pathlib.Path(__file__).with_name('front_gen.py'), run_name='front'); ch = g['ch']
def QR(items):
    return '<div class="qr">' + ''.join(f'<details class="qr-item"><summary>{q}</summary><div class="rep">{r}</div></details>' for q, r in items) + '</div>'
def T(rows, head): return '<div class="tablewrap"><table><tr>' + ''.join(f'<th>{h}</th>' for h in head) + '</tr>' + ''.join('<tr>' + ''.join(f'<td>{c}</td>' for c in r) + '</tr>' for r in rows) + '</table></div>'
def ET(items): return '<ol class="etapes">' + ''.join(f'<li>{x}</li>' for x in items) + '</ol>'
BREF = lambda theme: [f"Chaque question a une réponse modèle, cachée : lis la question, réponds à voix haute, puis compare.", f"Les réponses donnent la structure attendue ({theme}) ; remplace les exemples génériques par tes propres expériences, chiffrées.", "Une bonne réponse d'entretien tient en une à deux minutes : le principe, un exemple réel, et ce que tu ferais dans leur contexte."]
OBJ = ["Répondre avec assurance aux questions de ce thème", "Illustrer chaque réponse par un exemple vécu et chiffré", "Relier la réponse au contexte de la mission"]
TP = lambda theme: (f"Répétition « {theme} »", ["Masquer les réponses, répondre à voix haute à chaque question en moins de deux minutes.", "Noter les questions où la réponse hésite, relire le chapitre de cours correspondant, recommencer.", "Écrire pour trois questions ton propre exemple chiffré (situation, action, résultat)."],
                    "Attendu : toutes les questions du thème obtiennent une réponse claire, structurée et illustrée ; les trois exemples personnels sont prêts à être racontés.")

ENTRETIEN = [
ch("Entretien 1 — Se présenter, la mission, le rôle", 'e', BREF("posture et compréhension du poste"), OBJ,
 [("Se présenter", "", ET(["<strong>Qui je suis</strong> : Tech Lead Java expérimenté, MCO et MCS d'applications critiques, orientation DevSecOps.", "<strong>Le socle</strong> : Java 17, Spring, Hibernate, applications legacy (Struts), serveurs d'applications, Oracle, scripts d'exploitation, ordonnancement, GitLab CI et SonarQube.", "<strong>Une réussite chiffrée</strong> : par exemple une mise en production fiabilisée ou une vérification matinale automatisée (à remplacer par ton exemple).", "<strong>La posture</strong> : garant technique, pilotage d'un centre de services, qualité et sécurité par le processus.", "<strong>Pour ce poste</strong> : environnements identiques, sécurité des composants en fin de support, plan de migration."])),
  ("Questions et réponses", QR([
   ("Présentez-vous en deux minutes.", "Je suis les cinq points ci-dessus : identité professionnelle, socle technique, une réussite chiffrée, ma posture de Tech Lead, et pourquoi ce poste. Je termine par une phrase de lien : « c'est exactement le type de contexte où j'apporte le plus : garantir la production tout en la modernisant. »"),
   ("Pourquoi cette mission vous intéresse-t-elle ?", "Parce qu'elle combine trois choses que je sais faire et que j'aime faire : garantir une production critique (MCO), la sécuriser (MCS) et la faire évoluer (migrations), en pilotant un centre de services. Le socle (WildFly, Struts, Oracle, ordonnancement) correspond à des environnements que je connais et que je sais moderniser sans casser l'existant."),
   ("Qu'est-ce que le MCO pour vous ?", "Garantir que l'application rend le service attendu dans la durée. Il est correctif (réparer), adaptatif (suivre les évolutions de l'environnement : versions, infrastructure, réglementation) et évolutif (faire évoluer les fonctions). Concrètement : surveillance, ordonnancement, mises en production maîtrisées, gestion des incidents, documentation et amélioration continue."),
   ("Et le MCS ?", "C'est le maintien en condition de sécurité : transformer les alertes des moyens d'audit (SonarQube, analyse de dépendances, tests d'intrusion, scans) en correctifs livrés et prouvés, selon des délais liés à la gravité, avec des dérogations tracées quand un correctif est impossible, et une veille sur les bulletins de sécurité."),
   ("Quel est selon vous le rôle d'un Tech Lead expert ici ?", "Être le garant technique de bout en bout : environnements d'intégration et de production identiques, ordonnancement maîtrisé, mises en production sûres, qualité et sécurité des livrables du CDS, arbitrages techniques et migrations. Il code surtout les POC, les scripts et les corrections critiques, et il documente et communique."),
   ("Comment voyez-vous la relation avec le centre de services ?", "Un partenariat exigeant : des règles écrites et partagées (lignes de développement, barrière qualité, liste de revue), appliquées systématiquement, des retours précis et rapides, des indicateurs suivis, et un dialogue régulier. Je suis garant de la qualité, pas un contrôleur hostile."),
   ("Que ferez-vous pendant vos 30 premiers jours ?", "Cartographier l'application et les environnements, obtenir les accès, maîtriser la vérification matinale, accompagner une première mise en production, lire les incidents et rapports qualité récents ; à 30 jours, je présente un inventaire, les risques priorisés et mes premières propositions."),
   ("Avez-vous déjà travaillé dans un contexte sensible ou réglementé ?", "Oui (à illustrer par tes missions) : j'y ai appris la rigueur des procédures, la traçabilité des changements, la séparation des environnements et des droits, et l'importance de la documentation. Ces contraintes sont une garantie, pas un frein, si l'on outille les processus."),
   ("Quels sont vos points faibles par rapport à la fiche de poste ?", "Je réponds honnêtement sur un point précis (par exemple un ordonnanceur que je n'ai pas pratiqué) et je montre comment je le comble : les concepts sont communs aux outils, je les ai pratiqués sur un outil libre en conteneur, et je sais monter en compétence vite sur les commandes du site."),
   ("Comment vous tenez-vous à jour ?", "Par les bulletins de sécurité (CERT-FR, éditeurs), les notes de version (Java, WildFly, bibliothèques), une veille technique régulière, et surtout par la pratique : je reproduis en conteneur ce que j'apprends avant d'en parler ou de le proposer."),
   ("Êtes-vous disponible pour des interventions hors heures ouvrées ou l'astreinte ?", "Oui, c'est inhérent à une production critique. Mon objectif est d'en avoir le moins possible besoin : automatisation, runbooks, surveillance fiable, et mises en production préparées ; et quand j'interviens, je trace et je fais un retour d'expérience."),
   ("Pourquoi vous plutôt qu'un autre candidat ?", "Parce que j'ai à la fois la profondeur technique sur ce socle (serveur d'applications, Java, Oracle, scripts, ordonnancement), la pratique de la sécurité applicative, et l'expérience du pilotage : je sais garantir la production aujourd'hui et préparer sa modernisation, sans rupture."),
  ]), None)],
 [("Réponds en une minute : « Qu'apportez-vous dès la première semaine ? »", "Une cartographie rapide (accès, environnements, flux, ordonnancement), la maîtrise de la vérification matinale, et une première liste de risques ; je ne promets pas de transformation, je promets de la visibilité et de la fiabilité."),
  ("Question piège : « Vous semblez surqualifié pour du MCO. »", "Le MCO d'une application critique demande justement de l'expertise : garantir la production, la sécuriser et préparer sa migration sans incident est un travail d'expert ; c'est là que l'expérience évite les erreurs coûteuses.")],
 TP("présentation et rôle")),

ch("Entretien 2 — WildFly et environnements", 'e', BREF("WildFly, configuration, exploitation, migrations"), OBJ,
 [("Questions et réponses", QR([
   ("Mode autonome ou domaine : lequel utilisez-vous et pourquoi ?", "Autonome quand chaque serveur est configuré par des scripts versionnés et une chaîne de livraison, ce qui s'intègre bien aux conteneurs ; domaine quand on gère un parc homogène avec un contrôleur central (profils, groupes de serveurs, déploiements groupés). Le choix suit le parc, l'exploitation et les standards du site."),
   ("Comment configurez-vous une datasource Oracle ?", "Pilote déclaré comme module (com.oracle), pilote JDBC ajouté au sous-système datasources, puis datasource avec son nom JNDI, son pool (min, max, délai d'attente), la validation des connexions et le tri des exceptions Oracle, les statistiques activées et le mot de passe dans un magasin d'identifiants ; le tout par un script jboss-cli idempotent."),
   ("Pourquoi des scripts jboss-cli plutôt que la console ou l'édition du XML ?", "Parce qu'un script est versionné, relu, rejouable et identique en intégration et en production ; il sert de mode opératoire et de preuve. La console et l'édition manuelle ne laissent pas de trace fiable et créent des écarts entre environnements."),
   ("Que signifient reload-required et restart-required ?", "La configuration persistée a changé mais n'est pas active : un reload recharge la configuration sans arrêter la JVM, un restart redémarre le processus. On les planifie dans une fenêtre et on vérifie l'état du serveur après coup."),
   ("L'application ne répond plus alors que WildFly est démarré : votre démarche ?", "Statistiques du pool (épuisé ?), trois vidages des fils d'exécution espacés de dix secondes pour voir où ils attendent, sessions et verrous côté Oracle, journaux ; je soulage (tuer une requête bloquante, recharger si besoin) puis je traite la cause (connexion non rendue, index manquant, appel externe sans délai)."),
   ("Thread dump ou heap dump : quand utiliser l'un ou l'autre ?", "Le thread dump montre ce que font les fils d'exécution (blocages, attentes, boucles) : pour les lenteurs et les blocages. Le heap dump montre le contenu de la mémoire : pour les fuites et les OutOfMemoryError ; il est lourd et se prend avec précaution."),
   ("Qu'est-ce que jboss-deployment-structure.xml ?", "Le fichier qui règle le chargement des classes d'un déploiement : exclure un module ou un sous-système du serveur (par exemple JPA si l'application embarque son Hibernate), ajouter une dépendance à un module (le pilote Oracle). Il résout les conflits de versions entre l'application et le serveur."),
   ("Comment déployez-vous sans interruption de service ?", "Avec au moins deux instances derrière un répartiteur : on retire un nœud, on le suspend, on déploie, on contrôle, on le remet, puis on passe au suivant ; les sessions sont répliquées ou les utilisateurs acceptent une reconnexion. Sur une instance unique, on planifie une fenêtre courte et annoncée."),
   ("Comment sécurisez-vous l'interface de gestion ?", "Liée au réseau d'administration uniquement, en TLS, avec des utilisateurs nominatifs et l'audit des opérations activé ; jamais exposée sur le réseau des utilisateurs ni avec un compte partagé."),
   ("Qu'est-ce qu'Elytron ?", "Le sous-système de sécurité de WildFly depuis la version 25 : domaines de sécurité, royaumes (fichiers, LDAP, base de données, jetons), fabriques d'authentification, contextes TLS et magasins d'identifiants, pour l'application comme pour la gestion."),
   ("Comment activez-vous TLS ?", "Magasin de clés (PKCS12) avec le certificat, gestionnaire de clés, contexte SSL serveur (protocoles TLS 1.2 et 1.3), puis rattachement à l'écouteur HTTPS d'Undertow et à l'interface de gestion ; certificat suivi avec une alerte avant expiration."),
   ("Que change le passage de WildFly 26 à 27 et plus ?", "Le passage de Jakarta EE 8 à Jakarta EE 10 : les paquets javax.* deviennent jakarta.*. Toute application ou bibliothèque restée en javax (comme Struts 1) ne fonctionne plus telle quelle ; il faut inventorier, transformer ou migrer, et tester complètement."),
   ("Comment préparez-vous une montée de version de WildFly ?", "Inventaire (versions, dépendances javax, configurations spécifiques), scripts jboss-cli rejoués sur la nouvelle version, tests de non-régression, de charge et de sécurité en intégration, bascule planifiée avec retour arrière, documentation mise à jour."),
   ("WildFly ou JBoss EAP ?", "Même base technique ; EAP apporte le support éditeur et les correctifs de sécurité sur la durée, WildFly évolue plus vite sans support. En production critique, la décision dépend du contrat de support et de la politique de l'organisation."),
   ("Comment garantissez-vous que l'intégration est identique à la production ?", "Mêmes scripts de configuration avec un fichier de propriétés par environnement, mêmes artefacts versionnés, valeurs propres documentées, et une comparaison automatique des configurations avant chaque mise en production ; tout écart non documenté bloque la livraison."),
  ]), None)],
 [("Question piège : « Sur un seul serveur, comment mettez-vous à jour sans interruption ? »", "On ne peut pas garantir zéro interruption avec une seule instance : je propose une fenêtre courte et annoncée, préparée et répétée en intégration, ou l'ajout d'une seconde instance si le besoin métier l'exige ; je le dis clairement plutôt que de promettre l'impossible."),
  ("Explique en trente secondes le modèle de gestion de WildFly.", "Tout est ressource à une adresse (/subsystem=…), avec des attributs et des opérations ; la CLI, la console et l'API HTTP utilisent le même modèle, ce qui permet de tout scripter.")],
 TP("WildFly")),

ch("Entretien 3 — Ordonnancement, exploitation, Unix, Bash, PowerShell", 'e', BREF("ordonnancement et exploitation"), OBJ,
 [("Ordonnancement", QR([
   ("Quels concepts retrouve-t-on dans tous les ordonnanceurs ?", "Des jobs (commandes avec code retour), des chaînes (enchaînements), un plan du jour, des dépendances, des conditions ou événements, des calendriers, des fenêtres et heures limites, des ressources ; et des actions d'exploitation : relancer, forcer, mettre en attente, annuler."),
   ("Quels ordonnanceurs connaissez-vous ?", "Je cite ceux pratiqués et je montre la transposition : Control-M, VTOM, Dollar Universe, IBM Workload Scheduler, Autosys partagent les mêmes concepts sous des noms différents ; je me forme vite aux commandes et aux droits du site."),
   ("Qu'est-ce que la date d'exploitation ?", "La date métier traitée par la chaîne, fournie par l'ordonnanceur, différente de la date système : une chaîne qui passe minuit ou qui est relancée le lendemain traite toujours le bon jour. Les scripts la reçoivent en paramètre."),
   ("Qu'est-ce qu'un bon traitement ordonnancé ?", "Il renvoie un code retour fiable et documenté, écrit un journal exploitable, refuse les doubles lancements, se relance sans doublon, contrôle ses volumes, a un délai maximal, et sa conduite à tenir en cas d'échec est écrite."),
   ("Déroulez votre vérification matinale.", "Production puis intégration : plan de la nuit (erreurs, attentes, retards), analyse des jobs en erreur, heures limites et fichiers livrés, cohérence des volumes, état des serveurs et de la base, puis actions (relances, tickets, messages) et compte rendu à heure fixe."),
   ("Un job a échoué à 3 h et bloque les éditions. Il est 8 h : que faites-vous ?", "Je qualifie (code retour, journal, impact), je vérifie qu'une relance est sans risque (données présentes, idempotence), je relance puis je suis la suite de la chaîne, je préviens les utilisateurs du retard, j'ouvre un ticket pour la cause et j'enrichis la check-list si le cas est nouveau."),
   ("Forcer un job en succès, c'est acceptable ?", "Exceptionnellement, si l'on sait que le résultat existe par ailleurs ou n'est pas nécessaire à la suite, avec une justification, l'accord du responsable et une trace ; sinon on corrige et on relance, car un forçage fait croire à la suite que les données sont prêtes."),
   ("Comment relancer sans créer de doublons ?", "Grâce à des écritures idempotentes (table temporaire puis fusion, ou suppression du jour puis insertion) et des points de reprise ; un simple ajout rejoué crée forcément des doublons."),
   ("Quels pièges du calendrier anticipez-vous ?", "Changements d'heure (pas de planification entre 2 h et 3 h ou planification en UTC), fins de mois et d'année (volumes, traitements supplémentaires), jours fériés (calendriers relus chaque année), retards des partenaires (heures limites et plans de repli)."),
   ("Comment gérez-vous une dépendance vers la chaîne d'une autre équipe ?", "Par une condition explicite (fichier témoin, événement de fin) avec une heure limite, une alerte partagée et un plan de repli documenté ; jamais par un horaire supposé."),
   ("Comment testez-vous une modification de chaîne ?", "Définitions versionnées et relues, exécution complète en intégration avec la date du jour et des dates simulées (fin de mois), relance au milieu, vérification des alertes et des heures limites ; livraison par la chaîne, jamais de modification directe en production."),
  ]), None),
  ("Unix, Bash et PowerShell", QR([
   ("Un serveur est lent : vos cinq premières commandes ?", "uptime et top (charge, processus), free et vmstat (mémoire, attente d'entrées-sorties), df -h et df -i (disques, inodes), iostat (saturation disque), ss et journalctl (connexions, erreurs du service) ; en quelques minutes je sais si c'est la machine, l'application ou une dépendance."),
   ("Que fait set -Eeuo pipefail ?", "Arrêt à la première erreur (-e), refus des variables non définies (-u), échec d'un tube si une de ses commandes échoue (pipefail), propagation du piège ERR dans les fonctions (-E) : le script échoue clairement au lieu de continuer à moitié."),
   ("Comment écrivez-vous un script de purge sûr ?", "Mode strict, dossier vérifié (existence, préfixe attendu), recherche avec find -print0 et suppression fichier par fichier journalisée, mode essai à blanc, codes retour documentés, ShellCheck et tests ; jamais rm -rf sur une variable non contrôlée."),
   ("kill -TERM ou kill -KILL ?", "TERM demande un arrêt propre que le programme peut gérer ; KILL tue immédiatement sans rien terminer (transactions, fichiers). J'utilise d'abord l'arrêt applicatif ou TERM, KILL seulement si le processus ne répond plus, et je le trace."),
   ("Le disque est plein à cause des journaux : que faites-vous ?", "Dans l'urgence : identifier les gros fichiers récents, compresser ou déplacer, vider un journal ouvert par troncature plutôt que suppression ; puis durablement : rotation (logrotate), rétention, niveau de journal adapté, alerte à 80 % et volume dédié aux journaux."),
   ("Comment donnez-vous des droits d'exploitation sans donner root ?", "Par des règles sudo limitées aux commandes nécessaires (par exemple redémarrer un service), pour un groupe, journalisées ; les services tournent sous des comptes dédiés sans connexion interactive."),
   ("Qu'apporte PowerShell par rapport aux scripts .bat ?", "Il manipule des objets (plus de découpage de texte fragile), accède aux services, journaux d'événements, tâches planifiées et CIM, gère les erreurs, propose le mode essai à blanc (-WhatIf), l'administration à distance et les tests avec Pester."),
   ("Comment rendez-vous un script PowerShell robuste ?", "$ErrorActionPreference = 'Stop', blocs try et catch avec code de sortie, paramètres typés et obligatoires, SupportsShouldProcess pour -WhatIf, journal, tests Pester et analyse par PSScriptAnalyzer."),
   ("Comment cherchez-vous dans de très gros journaux en production ?", "En ciblant les fichiers et la période, avec zgrep sur les compressés, en baissant la priorité (nice, ionice), ou en copiant les fichiers utiles sur une machine d'analyse ; awk et jq pour résumer."),
  ]), None)],
 [("Question piège : « Que faites-vous si la chaîne de nuit a échoué et que personne ne vous a prévenu ? »", "La vérification matinale existe pour ça, mais je corrige aussi la cause de l'absence d'alerte : chaque échec de job critique doit notifier l'astreinte, et je vérifie que la notification fonctionne."),
  ("Explique en trente secondes la différence entre cron et un ordonnanceur d'entreprise.", "cron lance des commandes à heure fixe sur une machine ; un ordonnanceur gère des chaînes multi-serveurs avec dépendances, conditions, calendriers, reprises, historique et supervision centralisée.")],
 TP("ordonnancement et exploitation")),

ch("Entretien 4 — Oracle, SQL et PL/SQL", 'e', BREF("Oracle et bases de données"), OBJ,
 [("Questions et réponses", QR([
   ("Comment trouvez-vous qui bloque qui ?", "Dans v$session, la colonne blocking_session indique la session bloquante ; on regarde son état, sa requête (sql_id) et depuis quand elle attend. On décide ensuite avec le DBA : attendre, faire valider la transaction, ou tuer la session."),
   ("Comment analysez-vous une requête lente ?", "Je récupère son sql_id, j'affiche le plan réel avec DBMS_XPLAN.DISPLAY_CURSOR (ALLSTATS LAST), je compare estimations et lignes réelles, je cherche les accès complets inattendus, les index manquants ou les statistiques périmées, puis je teste la correction en intégration."),
   ("Une requête est devenue lente du jour au lendemain sans changement de code. Pourquoi ?", "Souvent un changement de plan : statistiques recalculées ou périmées, volume qui a franchi un seuil, valeurs de paramètres différentes à l'analyse ; je compare les plans avant et après et je corrige la cause (statistiques, index, profil ou réécriture)."),
   ("Quand créez-vous un index ?", "Pour les colonnes filtrées ou jointes souvent et sélectives, les clés étrangères (surtout si l'on supprime dans la table parente), et les tris fréquents ; en mesurant le gain, car chaque index coûte en écriture et en espace."),
   ("Pourquoi BULK COLLECT et FORALL ?", "Pour traiter par lots au lieu de ligne à ligne et réduire les allers-retours entre PL/SQL et SQL : gain souvent d'un ordre de grandeur ; LIMIT borne la mémoire et une validation par lot permet la reprise."),
   ("Que pensez-vous de WHEN OTHERS THEN NULL ?", "C'est dangereux : l'erreur disparaît silencieusement. On journalise l'erreur avec son contexte puis on la relance (RAISE), ou on traite précisément les exceptions attendues."),
   ("Faut-il valider (COMMIT) dans une boucle ?", "Pas à chaque ligne (lent et reprise difficile), mais par lot sur les gros traitements, avec un suivi qui permet de reprendre ; pour une opération métier cohérente, une seule transaction."),
   ("Comment livrez-vous un script SQL en production ?", "Script numéroté et versionné, testé en intégration sur un volume réaliste, idempotent si possible, avec son script de retour arrière, une sauvegarde préalable si nécessaire, et un outil de migration (Flyway ou Liquibase) qui trace ce qui a été joué."),
   ("Séquence ou colonne identity ?", "Les deux génèrent des identifiants ; identity (Oracle 12c et plus) lie la génération à la colonne et simplifie, la séquence reste utile quand plusieurs tables partagent une numérotation ou pour l'existant. Dans les deux cas, on ne suppose pas de numéros sans trous."),
   ("Comment paginez-vous en Oracle ?", "Avec OFFSET … FETCH FIRST n ROWS ONLY (12c et plus), ou ROWNUM dans une sous-requête triée sur les versions anciennes ; sur de gros volumes, une pagination par clé (WHERE id > dernier_id) est plus performante."),
   ("À quoi sert MERGE ?", "À insérer ou mettre à jour en une seule instruction selon qu'une ligne correspond (upsert) : idéal pour des chargements idempotents à partir d'une table temporaire."),
   ("Quelle est la différence entre Data Pump et une sauvegarde de la base ?", "Data Pump exporte et importe des objets et des données logiquement (schéma, tables), pratique avant une opération risquée ou pour copier un schéma ; la sauvegarde physique (RMAN, gérée par les DBA) protège toute la base avec restauration à un instant donné."),
  ]), None)],
 [("Question piège : « Vous n'êtes pas DBA, jusqu'où allez-vous ? »", "Je diagnostique (sessions, verrous, plans), je corrige ce qui relève de l'application (requêtes, index applicatifs, scripts), et je travaille avec les DBA pour ce qui relève de la base (paramètres, sauvegardes, stockage) ; je sais parler leur langage."),
  ("Explique en trente secondes un plan d'exécution.", "C'est le chemin choisi par l'optimiseur pour exécuter la requête : accès aux tables (complet ou par index), méthodes de jointure, ordre des opérations, avec des estimations de lignes et de coût ; on le lit de l'intérieur vers l'extérieur.")],
 TP("Oracle")),

ch("Entretien 5 — Java 17, Struts 1, Spring et Hibernate", 'e', BREF("Java et frameworks de l'application"), OBJ,
 [("Java 17 et plus", QR([
   ("Qu'apportent Java 17 et 21 par rapport à Java 8 ?", "Au langage : var, expressions switch, blocs de texte, records, classes scellées, pattern matching (instanceof puis switch en 21) ; à la plateforme : meilleures performances et GC (G1 par défaut, ZGC), outils (JFR, jcmd), encapsulation forte des API internes ; en 21, les threads virtuels."),
   ("Comment migrez-vous de Java 8 ou 11 vers 17 ?", "Inventaire avec jdeps et jdeprscan, mise à jour des dépendances et plugins, ajout des modules retirés du JDK en Java 11 (JAXB, JAX-WS…) comme dépendances, recettes OpenRewrite, compilation et tests complets, puis déploiement en intégration avant la production ; les --add-opens restent l'exception documentée."),
   ("À quoi servent records et classes scellées ?", "Les records définissent des objets de données immuables en une ligne (constructeur, accesseurs, equals, hashCode, toString) ; les classes scellées ferment une hiérarchie, ce qui rend les switch exhaustifs vérifiés par le compilateur."),
   ("Quel ramasse-miettes choisir ?", "G1 par défaut convient à la plupart des applications ; ZGC pour de très grands tas avec des pauses très courtes ; le choix se valide par des mesures (journaux du GC, JFR) sous charge réaliste."),
   ("Comment diagnostiquez-vous une fuite mémoire ?", "Journaux du GC qui montrent un tas qui ne redescend pas, vidage mémoire analysé avec Eclipse MAT (plus gros consommateurs, chemins vers les racines), puis correction (cache non borné, collection statique, sessions trop lourdes) et vérification sous charge."),
   ("Que sont les threads virtuels ?", "Des fils d'exécution très légers gérés par la JVM (Java 21), qui permettent des milliers de tâches bloquantes simultanées sans pool coûteux ; utiles pour des services d'entrées-sorties, à condition d'éviter les blocs synchronisés longs et de vérifier les bibliothèques."),
  ]), None),
  ("Struts 1", QR([
   ("Décrivez le cycle d'une requête Struts 1.", "L'ActionServlet reçoit la requête, le RequestProcessor trouve le mapping dans struts-config.xml, remplit et valide l'ActionForm (Validator), appelle Action.execute, qui renvoie un ActionForward vers une JSP (souvent via Tiles)."),
   ("Quels risques présente Struts 1 aujourd'hui ?", "Il est en fin de support depuis 2013 : des vulnérabilités connues ne seront jamais corrigées (par exemple la manipulation du chargeur de classes par un paramètre « class », CVE-2014-0114). On filtre les paramètres dangereux, on met un WAF, on tient les dépendances à jour et on planifie la sortie."),
   ("Comment feriez-vous sortir une application de Struts 1 ?", "Progressivement : tests de caractérisation, puis migration écran par écran vers Spring MVC derrière les mêmes URL (étranglement), en réutilisant les services existants ; jamais de réécriture complète d'un coup."),
   ("ActionForm ou DynaActionForm ?", "ActionForm est une classe écrite pour chaque formulaire ; DynaActionForm déclare ses propriétés dans struts-config.xml sans classe. Dans l'existant on trouve les deux ; la validation se fait avec le Validator dans les deux cas."),
  ]), None),
  ("Spring et Hibernate", QR([
   ("Qu'est-ce que l'inversion de contrôle et l'injection de dépendances ?", "Le conteneur Spring crée les objets et leur fournit leurs dépendances au lieu qu'ils les créent eux-mêmes : le code est découplé, testable (on injecte des doublures) et configurable."),
   ("Pourquoi une méthode @Transactional peut-elle ne pas être transactionnelle ?", "Parce que la transaction est posée par un proxy : un appel interne (this.methode()) ne passe pas par le proxy, et une méthode non publique n'est pas interceptée. On appelle via un autre bean et on vérifie la propagation."),
   ("Spring ou Spring Boot ?", "Spring est le cadre (IoC, AOP, transactions, MVC) ; Spring Boot ajoute l'autoconfiguration, les dépendances de démarrage et le serveur embarqué. Dans une application déployée sur WildFly, on trouve souvent Spring classique en WAR."),
   ("Qu'est-ce que le problème N+1 ?", "Une requête pour charger une liste, puis une requête par élément pour ses associations paresseuses ; on le détecte en comptant les requêtes (journal SQL) et on le corrige par fetch join, batch-size ou projection."),
   ("LazyInitializationException : cause et solution ?", "On accède à une association paresseuse après fermeture de la session Hibernate ; on charge ce qu'il faut dans la couche service (fetch join, graphe d'entités) au lieu d'élargir la session jusqu'à la vue."),
   ("Cache de premier et de second niveau ?", "Le premier niveau est la session : chaque entité n'y est chargée qu'une fois. Le second niveau est partagé entre sessions, réservé aux données de référence peu modifiées, avec une expiration ; mal utilisé, il affiche des données périmées."),
   ("Comment gérez-vous les accès concurrents avec Hibernate ?", "Par le verrouillage optimiste (@Version) : une mise à jour concurrente lève une exception gérée proprement ; le verrouillage pessimiste reste réservé aux cas précis et courts."),
   ("hbm.xml ou annotations ?", "Les annotations sont le standard actuel ; dans l'existant on trouve des mappings hbm.xml : on garde un seul style par entité, et on migre progressivement avec des tests de mapping."),
  ]), None)],
 [("Question piège : « Réécririez-vous l'application en Spring Boot ? »", "Pas d'un coup : je sécurise l'existant, puis je migre par étapes selon la valeur et le risque, avec des tests à chaque étape ; la réécriture complète est rarement la meilleure réponse pour une application critique."),
  ("Explique en trente secondes le rôle d'Hibernate.", "Il fait correspondre des objets Java et des tables (ORM), génère le SQL, gère sessions, cache et transactions ; il faut surveiller le SQL généré pour éviter les requêtes inefficaces.")],
 TP("Java et frameworks")),

ch("Entretien 6 — XML et services web REST et SOAP", 'e', BREF("XML et services web"), OBJ,
 [("Questions et réponses", QR([
   ("XSD ou DTD ?", "La XSD est un schéma riche (types, cardinalités, espaces de noms) écrit en XML ; la DTD est plus ancienne et plus limitée. On valide les échanges par XSD."),
   ("DOM, SAX ou StAX ?", "DOM charge tout le document en mémoire (pratique, coûteux) ; SAX lit en flux par événements (léger, moins pratique) ; StAX lit en flux à la demande (bon compromis) : pour les gros fichiers, un analyseur en flux."),
   ("Qu'est-ce qu'une attaque XXE et comment l'éviter ?", "Un document XML déclare une entité externe (fichier local, adresse interne) que l'analyseur résout : lecture de fichiers ou requêtes internes. On interdit les DOCTYPE et les entités externes dans la configuration de l'analyseur."),
   ("À quoi servent les espaces de noms ?", "À éviter les collisions de noms entre vocabulaires XML ; un élément est identifié par son espace de noms et son nom local, ce qui compte en XPath et en validation."),
   ("SOAP ou REST ?", "REST et JSON pour la plupart des nouveaux échanges, plus simples ; SOAP quand le partenaire l'impose ou qu'on a besoin de contrats stricts (WSDL) et de WS-Security. Dans l'existant, on maintient SOAP proprement."),
   ("Contrat d'abord ou code d'abord ?", "Contrat d'abord (WSDL ou OpenAPI écrit puis code généré) pour les échanges avec des partenaires : le contrat est stable et partagé ; code d'abord pour des services internes simples. Dans les deux cas, le contrat est versionné."),
   ("Qu'est-ce que WS-Security ?", "Un standard SOAP pour sécuriser les messages eux-mêmes : jetons (nom d'utilisateur, certificats), signature et chiffrement de parties du message, horodatage ; il complète TLS, qui ne protège que le transport."),
   ("Quelles méthodes HTTP sont idempotentes ?", "GET, PUT et DELETE (et HEAD, OPTIONS) : les répéter a le même effet ; POST ne l'est pas, d'où les clés d'idempotence pour les créations rejouées."),
   ("Comment versionnez-vous une API REST ?", "Par l'URL (/v1/) ou un en-tête, avec des changements rétrocompatibles tant que possible (ajouts), une dépréciation annoncée pour les ruptures, et des tests de contrat."),
   ("Comment testez-vous un service SOAP ?", "Avec SoapUI (projets versionnés) pour l'exploration et les tests fonctionnels, et des tests d'intégration automatisés en CI (client généré depuis le WSDL, serveur de test en conteneur)."),
  ]), None)],
 [("Question piège : « TLS suffit-il à sécuriser un service SOAP ? »", "TLS protège le transport de bout en bout d'une connexion ; si le message transite par des intermédiaires ou doit être signé pour preuve, WS-Security ajoute signature et chiffrement au niveau du message."),
  ("Explique en trente secondes XPath.", "Un langage pour désigner des nœuds d'un document XML par un chemin et des conditions, utilisé pour extraire des valeurs, dans XSLT et dans la validation.")],
 TP("XML et services web")),

ch("Entretien 7 — CI/CD, GitLab CI, Jenkins, SonarQube, Jira, Confluence", 'e', BREF("chaîne de livraison et outils"), OBJ,
 [("Questions et réponses", QR([
   ("Décrivez votre chaîne CI/CD type pour une application Java.", "Construction Maven, tests unitaires et d'intégration, analyse SonarQube avec attente de la barrière, analyse des dépendances, paquet versionné publié, déploiement automatique en intégration par les scripts de configuration, et production déclenchée manuellement sur un tag, avec le même script."),
   ("Quelles notions de GitLab CI utilisez-vous ?", "stages et jobs, rules pour conditionner, needs pour paralléliser, artefacts et cache, environments (intégration, production), jobs manuels protégés, variables masquées et protégées, includes et modèles partagés, runners dédiés."),
   ("Comment gérez-vous les secrets dans la CI ?", "Variables masquées et protégées (uniquement sur les branches protégées), ou mieux un coffre (Vault) avec identité de la CI ; jamais de secret dans le dépôt, et une détection de secrets dans la chaîne."),
   ("Jenkins : pipeline déclaratif ou scripté ?", "Déclaratif par défaut (structure lisible, options, post), scripté pour les cas très dynamiques ; les étapes communes vont dans des shared libraries versionnées."),
   ("Qu'est-ce que la barrière qualité SonarQube ?", "Un ensemble de conditions que le code doit remplir pour être accepté, en général sur le nouveau code : couverture, duplications, notes de fiabilité, de sécurité et de maintenabilité, points sensibles revus. La chaîne échoue si elle n'est pas respectée."),
   ("Pourquoi la barrière porte-t-elle sur le nouveau code ?", "Pour garantir que chaque changement est propre sans exiger de rattraper tout l'existant d'un coup ; la dette diminue au fil des modifications, et l'existant à risque est traité par un plan séparé."),
   ("Que faites-vous si le CDS livre avec une barrière rouge « car c'est urgent » ?", "Je ne l'accepte pas en l'état sauf dérogation écrite, datée et justifiée par un risque métier, avec les corrections exigées dans un délai court et une trace dans Jira ; sinon la barrière perd tout son sens."),
   ("Que sont les points sensibles de sécurité (hotspots) ?", "Des portions de code sensibles que SonarQube demande de revoir (cryptographie, désérialisation, expressions régulières…) : un humain décide si c'est sûr ou à corriger, et la décision est tracée."),
   ("Comment organisez-vous Jira pour le MCO et le MCS ?", "Types de tickets distincts (anomalie, évolution, MCS, mise en production), workflow simple avec des états clairs, labels et versions, filtres JQL et tableau de bord (anomalies par gravité, MCS par échéance, versions en cours)."),
   ("Donnez un exemple de requête JQL utile.", "project = APP AND labels = MCS AND duedate < endOfWeek() AND statusCategory != Done : les vulnérabilités à traiter cette semaine et pas encore closes."),
   ("Comment structurez-vous Confluence ?", "Un espace par application avec des modèles : dossier d'exploitation, modes opératoires, runbooks par incident, fiches de version, décisions d'architecture ; pages datées et relues, reliées aux tickets Jira."),
   ("GitLab CI ou Jenkins ?", "GitLab CI s'intègre au dépôt et simplifie la maintenance ; Jenkins est très extensible et souvent déjà en place. Je travaille avec les deux, et une migration se fait progressivement, projet par projet, si c'est la stratégie de l'organisation."),
   ("Comment supervisez-vous la CI/CD du CDS ?", "Modèles de pipeline communs, barrières obligatoires, indicateurs (durée, taux d'échec, délai des MR), revue régulière avec le CDS, et amélioration continue des modèles."),
  ]), None)],
 [("Question piège : « La barrière bloque tout le monde, faut-il la baisser ? »", "Pas sans analyse : je regarde quelles conditions bloquent et pourquoi (tests manquants, faux positifs, règles inadaptées), j'ajuste ce qui est injustifié, et j'aide l'équipe sur le reste ; la barrière doit être exigeante et réaliste."),
  ("Explique en trente secondes l'intérêt d'un pipeline identique pour intégration et production.", "Si le même artefact et le même script passent partout, ce qui a marché en intégration a toutes les chances de marcher en production ; chaque différence est une source d'incident.")],
 TP("CI/CD et outils")),

ch("Entretien 8 — MCO, MCS, sécurité et migrations", 'e', BREF("sécurité et évolution de l'existant"), OBJ,
 [("Questions et réponses", QR([
   ("Décrivez votre processus MCS.", "Collecte des alertes (SonarQube, dépendances, images, tests d'intrusion, scans, bulletins), consolidation et dédoublonnage, tri selon la gravité, l'exploitabilité et l'exposition, tickets avec délais, correctifs testés en intégration, preuve de fermeture, et dérogations tracées si nécessaire."),
   ("Comment priorisez-vous 300 vulnérabilités ?", "Je regroupe par composant (quelques bibliothèques expliquent souvent la majorité), je traite d'abord ce qui est critique, exploité (EPSS, catalogue des vulnérabilités exploitées) et exposé, j'élimine les faux positifs, puis je planifie des lots de mises à jour."),
   ("Comment prouvez-vous qu'une vulnérabilité est corrigée ?", "Nouveau scan de la version déployée qui ne la remonte plus, et si possible un test reproduisant l'exploitation qui échoue désormais ; la preuve est jointe au ticket avant fermeture."),
   ("Que faites-vous si aucun correctif n'est possible ?", "Une dérogation : risque décrit, mesures compensatoires (filtrage, WAF, isolement réseau, surveillance), date de réexamen, validation par le responsable sécurité ; jamais permanente."),
   ("Une faille critique est publiée un vendredi soir sur une bibliothèque que vous utilisez. Votre réaction ?", "Vérifier en quelques minutes si nous sommes concernés (inventaire des dépendances, version, exposition), appliquer une mesure de protection immédiate si possible (configuration, filtrage), informer le responsable sécurité, préparer et tester le correctif en intégration, puis le déployer selon la procédure d'urgence et tracer."),
   ("Quelles vulnérabilités applicatives cherchez-vous en priorité dans une application legacy ?", "Injections (SQL, XXE), contrôle d'accès côté serveur, authentification et sessions, données sensibles en clair, composants vulnérables ou en fin de support, erreurs de configuration ; c'est le socle du Top 10 OWASP."),
   ("Comment gérez-vous les secrets de l'application ?", "Hors du code et des dépôts : magasin d'identifiants du serveur ou coffre, rotation régulière et après toute exposition, droits minimaux par compte, détection de secrets dans la CI."),
   ("Comment planifiez-vous une migration technique ?", "Inventaire et risques, options chiffrées, POC sur l'option retenue, plan par étapes avec critères de passage, tests (non-régression, charge, sécurité) en intégration, bascule avec retour arrière, accompagnement des équipes et mise à jour de la documentation."),
   ("Comment migreriez-vous Java, WildFly et Struts en même temps ?", "Pas en même temps : j'enchaîne les étapes pour isoler les risques (par exemple Java 17 sur la plateforme actuelle, puis la couche web, puis le serveur d'applications), avec des tests à chaque étape et une production stable entre deux."),
   ("À quoi servent les tests de charge dans ce contexte ?", "À vérifier que l'application tient la charge réelle et les pics (fin de mois) après un changement, et à dimensionner pools et mémoire ; ils se font en intégration avec une configuration identique à la production."),
   ("Qu'est-ce que la réversibilité ?", "La capacité à transmettre la prestation à un tiers : documentation d'exploitation, modes opératoires, runbooks, inventaire, accès et connaissances, avec un planning de transfert ; on la prépare dès le début, pas à la fin."),
   ("Comment gérez-vous les mises à jour du middleware (Java, WildFly, pilote Oracle) ?", "Veille des versions et bulletins, planification régulière, mise à jour testée en intégration avec les mêmes scripts, fiche de version, déploiement en production dans une fenêtre, retour arrière prêt."),
  ]), None)],
 [("Question piège : « Pourquoi ne pas simplement tout mettre à jour chaque mois ? »", "Mettre à jour régulièrement est souhaitable, mais chaque mise à jour se teste ; je propose un rythme soutenable (lots planifiés, urgences traitées à part) plutôt qu'une promesse qui dégraderait la stabilité."),
  ("Explique en trente secondes CVSS et EPSS.", "CVSS mesure la gravité théorique d'une vulnérabilité ; EPSS estime la probabilité qu'elle soit exploitée prochainement. On combine les deux avec l'exposition réelle du composant pour prioriser.")],
 TP("sécurité et migrations")),

ch("Entretien 9 — Pilotage du CDS, devis, POC, spécifications, accréditations", 'e', BREF("pilotage et gouvernance"), OBJ,
 [("Questions et réponses", QR([
   ("Comment menez-vous une revue de code du CDS ?", "Avec une liste partagée (lignes de développement, couches, gestion d'erreurs, requêtes paramétrées, sécurité, tests, barrière qualité), des remarques classées par gravité, précises et actionnables, et un délai de retour court."),
   ("Que vérifiez-vous dans un livrable ?", "Artefact versionné et fiche de version, scripts SQL et de configuration numérotés avec retour arrière, mode opératoire, notes de version, documentation à jour, barrière qualité verte et tests de recette passés."),
   ("Comment analysez-vous un devis ?", "Je vérifie périmètre, hypothèses, chiffrage (comparé à des tâches similaires), oublis (tests, documentation, sécurité, performance, recette), risques et critères d'acceptation ; mes remarques sont écrites et précises."),
   ("Le CDS propose 40 jours là où vous en estimez 20. Que faites-vous ?", "Je demande le détail par tâche, je compare aux abaques et à l'historique, je repère les écarts (hypothèses, risques surestimés, périmètre élargi) et j'en discute sans conflit ; on aboutit à un chiffrage justifié ou à un périmètre revu."),
   ("Comment cadrez-vous un POC ?", "Une question précise, une durée bornée, des critères de réussite mesurables et une conclusion écrite : on garde, on jette ou on approfondit ; un POC n'est pas une mise en production déguisée."),
   ("Que contient une spécification technique ?", "Le contexte, les règles de gestion techniques à respecter (interfaces, formats, performances, sécurité, exploitation : journaux, codes retour, ordonnancement), les impacts, les critères de recette et les points ouverts."),
   ("Qu'appelez-vous lignes de développement ?", "Les règles communes du projet : architecture en couches, conventions, gestion des erreurs et des journaux, sécurité, tests, dépendances autorisées ; elles sont écrites, partagées et vérifiées en revue et par la barrière qualité."),
   ("Comment gérez-vous les accréditations ?", "Demande par ticket, validation par le représentant des utilisateurs, attribution au moindre privilège, traçabilité, revue périodique des droits et retrait au départ ou au changement de poste, séparation des tâches."),
   ("Un responsable exige des droits d'administration immédiatement. Que faites-vous ?", "Je respecte le processus en accélérant ce qui peut l'être : ticket, validation rapide par le bon représentant, droit minimal et limité dans le temps ; s'il existe une procédure d'urgence, je l'applique avec retrait et revue a posteriori."),
   ("Comment communiquez-vous auprès des parties prenantes ?", "Messages courts et structurés à des moments fixes (annonce, début, fin d'une mise en production, incident et rétablissement), avec impact, actions et prochaines étapes ; des comptes rendus écrits après les réunions."),
   ("Quels indicateurs suivez-vous pour piloter ?", "Incidents par gravité et délai de résolution, taux de réussite des mises en production, vulnérabilités ouvertes par échéance, barrière qualité et couverture du nouveau code, délai des MR, respect des heures limites des chaînes."),
   ("Comment travaillez-vous avec l'architecte ?", "En amont des évolutions : je remonte les contraintes d'exploitation et de sécurité, il porte la cohérence d'ensemble ; nous tranchons ensemble les choix structurants et les écrivons dans des décisions d'architecture."),
  ]), None)],
 [("Question piège : « Le CDS n'est pas sous votre autorité : comment obtenez-vous la qualité ? »", "Par le cadre (règles écrites, barrière, critères d'acceptation contractuels), la régularité des retours, la transparence des indicateurs et la relation ; et en escaladant avec des faits quand c'est nécessaire."),
  ("Explique en trente secondes la séparation des tâches.", "Une même personne ne doit pas pouvoir demander, valider et attribuer ses propres droits, ni développer et mettre en production seule sans contrôle : on répartit les étapes sensibles entre plusieurs personnes.")],
 TP("pilotage et gouvernance")),

ch("Entretien 10 — Mises en situation, comportement et questions à poser", 'e', BREF("mises en situation"), OBJ,
 [("Mises en situation", QR([
   ("Racontez une mise en production qui s'est mal passée.", "STAR sans esquive : le contexte, ce qui a échoué (par exemple un écart de configuration non détecté), la décision (retour arrière à l'heure prévue), le résultat (service rétabli, communication faite) et ce qui a changé ensuite (comparaison automatique des configurations)."),
   ("Un incident majeur touche la production en pleine journée. Comment vous organisez-vous ?", "Je qualifie l'impact, je mobilise les bonnes personnes, je sépare diagnostic et communication, j'applique la mesure de rétablissement la plus sûre, je communique à intervalles réguliers, puis je mène un post-mortem sans blâme avec des actions datées."),
   ("Vous êtes en désaccord avec l'architecte sur un choix technique.", "J'expose mes arguments avec des faits (risques, coûts, exploitation), j'écoute les siens, nous cherchons une option commune ou un POC pour trancher, et une fois la décision prise et écrite, je la soutiens."),
   ("Le CDS est en retard sur une livraison critique.", "Je comprends la cause (périmètre, dépendance, compétence), je propose un découpage pour livrer l'essentiel à temps, j'informe les parties prenantes tôt avec un nouveau plan, et je traite la cause pour la suite."),
   ("Racontez une erreur que vous avez commise.", "Une vraie erreur, assumée : ce qui s'est passé, comment je l'ai détectée et corrigée, ce qu'elle a coûté, et le garde-fou mis en place pour qu'elle ne se reproduise pas ; la leçon compte plus que l'erreur."),
   ("La maîtrise d'ouvrage veut une évolution tout de suite, la sécurité exige d'abord un correctif.", "Je rends le conflit visible avec les risques de chaque option, je propose un ordre ou un compromis (correctif en urgence, évolution juste après), et je fais trancher par le bon niveau de décision, par écrit."),
   ("On vous demande de mettre en production sans avoir testé en intégration.", "Je refuse poliment en expliquant le risque, et je propose une voie rapide : test ciblé en intégration dans l'heure, fenêtre dédiée, retour arrière prêt ; s'il y a vraiment urgence, la décision et le risque sont assumés par écrit au bon niveau."),
   ("Comment convaincriez-vous de lancer une migration de Struts 1 ?", "Avec des faits : vulnérabilités non corrigées, blocage des montées de version du serveur et de Java, coût croissant du MCO ; puis un plan progressif chiffré et un POC qui réduit l'incertitude."),
   ("Comment transmettez-vous vos connaissances ?", "Documentation à jour (dossier d'exploitation, runbooks), binômes sur les opérations sensibles, courtes sessions de partage, et réversibilité préparée en continu ; personne ne doit être irremplaçable, moi compris."),
   ("Un membre de l'équipe contourne régulièrement les règles (mises en production directes).", "Je lui en parle en tête à tête, avec les faits et les risques, je comprends ce qui le pousse (procédure trop lourde ?), j'ajuste ce qui peut l'être, et si cela continue, j'en parle au responsable ; les règles protègent aussi celui qui les suit."),
  ]), None),
  ("Questions à poser en fin d'entretien", QR([
   ("Quel ordonnanceur utilisez-vous et comment est organisée la vérification matinale ?", "Cette question montre que tu te projettes sur une tâche quotidienne clé et t'aide à préparer tes premiers jours."),
   ("Quel est le rythme des mises en production et comment se passent-elles ?", "Tu évalues la maturité du processus (fenêtres, ISO, retour arrière) et les points à améliorer."),
   ("Où en sont les composants en fin de support et quelle est la stratégie de migration ?", "Tu montres ta compréhension des enjeux (Struts 1, WildFly, Java) et tu identifies les chantiers à venir."),
   ("Comment fonctionne la collaboration avec le centre de services et la barrière qualité ?", "Tu évalues le cadre existant (contrat, règles, indicateurs) et ton levier réel."),
   ("Quels sont aujourd'hui les principaux irritants ou incidents récurrents ?", "Tu obtiens les priorités réelles et tu peux relier ton expérience à leurs problèmes concrets."),
  ]), None)],
 [("Question piège : « Qu'est-ce qui pourrait vous faire échouer dans ce poste ? »", "Arriver en voulant tout changer sans comprendre l'existant ; c'est pourquoi je commence par cartographier, fiabiliser et écouter, avant de proposer des évolutions."),
  ("Termine l'entretien en trente secondes.", "Je résume ce que j'ai compris de leurs enjeux, en quoi mon expérience y répond, et je dis clairement mon intérêt pour la mission, avant de demander les prochaines étapes.")],
 TP("mises en situation")),
]
